    fn make_mixed_scan_comparison() -> sloc_core::ScanComparison {
        sloc_core::ScanComparison {
            summary: sloc_core::SummaryDelta {
                baseline_run_id: "base".to_string(),
                current_run_id: "curr".to_string(),
                baseline_timestamp: chrono::Utc::now(),
                current_timestamp: chrono::Utc::now(),
                baseline_files: 4,
                current_files: 4,
                files_analyzed_delta: 0,
                baseline_code: 330,
                current_code: 400,
                code_lines_delta: 70,
                baseline_comments: 0,
                current_comments: 0,
                comment_lines_delta: 0,
                blank_lines_delta: 0,
                total_lines_delta: 70,
                coverage_lines_hit_delta: None,
                coverage_line_pct_delta: None,
                baseline_coverage_line_pct: None,
                current_coverage_line_pct: None,
            },
            file_deltas: vec![
                sloc_core::FileDelta {
                    relative_path: "added.rs".to_string(),
                    language: Some("Rust".to_string()),
                    status: FileChangeStatus::Added,
                    baseline_code: 0,
                    current_code: 100,
                    code_delta: 100,
                    baseline_comment: 0,
                    current_comment: 0,
                    comment_delta: 0,
                    baseline_blank: 0,
                    current_blank: 0,
                    blank_delta: 0,
                    total_delta: 100,
                },
                sloc_core::FileDelta {
                    relative_path: "removed.rs".to_string(),
                    language: Some("Rust".to_string()),
                    status: FileChangeStatus::Removed,
                    baseline_code: 50,
                    current_code: 0,
                    code_delta: -50,
                    baseline_comment: 0,
                    current_comment: 0,
                    comment_delta: 0,
                    baseline_blank: 0,
                    current_blank: 0,
                    blank_delta: 0,
                    total_delta: -50,
                },
                sloc_core::FileDelta {
                    relative_path: "modified.rs".to_string(),
                    language: Some("Rust".to_string()),
                    status: FileChangeStatus::Modified,
                    baseline_code: 80,
                    current_code: 100,
                    code_delta: 20,
                    baseline_comment: 0,
                    current_comment: 0,
                    comment_delta: 0,
                    baseline_blank: 0,
                    current_blank: 0,
                    blank_delta: 0,
                    total_delta: 20,
                },
                sloc_core::FileDelta {
                    relative_path: "unchanged.rs".to_string(),
                    language: Some("Rust".to_string()),
                    status: FileChangeStatus::Unchanged,
                    baseline_code: 200,
                    current_code: 200,
                    code_delta: 0,
                    baseline_comment: 0,
                    current_comment: 0,
                    comment_delta: 0,
                    baseline_blank: 0,
                    current_blank: 0,
                    blank_delta: 0,
                    total_delta: 0,
                },
            ],
            files_added: 1,
            files_removed: 1,
            files_modified: 1,
            files_unchanged: 1,
            files_total: 4,
        }
    }

